action.command:
node -e "
const fs = require('fs');
const path = require('path');
let input = '';
process.stdin.on('data', d => input += d);
process.stdin.on('end', () => {
  const ctx = JSON.parse(input);
  const ws = ctx.workspacePath || ctx.workspaceFolder || ctx.workspace || process.env.WORKSPACE || '/Users/asims/Code/escrow-desk';
  const logPath = path.join(ws, 'docs/AI-log/session-log.md');
  const ts = new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC';
  const prompt = (ctx.userPrompt || ctx.prompt || '').replace(/\n/g, '\n> ');
  const entry = '\n## ' + ts + '\n\n**User:** ' + prompt + '\n';
  fs.appendFileSync(logPath, entry);
});
"
